  --surface-soft: oklch(95% 0.02 255);
  --text: oklch(20% 0.02 255);
  --text-inverse: oklch(97% 0.01 255);
  --muted: oklch(60% 0.03 255);
  --primary: oklch(67% 0.2 45);
  --primary-strong: oklch(60% 0.22 45);
  --accent: oklch(72% 0.17 150);
  --border: oklch(88% 0.02 255);
  --success: oklch(70% 0.16 150);
  --danger: oklch(62% 0.23 25);
  --container: 1120px;
  --radius: 14px;
  --shadow: 0 12px 28px oklch(20% 0.03 255 / 0.16);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, "Segoe UI", Roboto, system-ui, -apple-system, sans-serif;
  color: var(--text);
  background: var(--surface);
  line-height: 1.6;
}
h1, h2, h3, h4 { font-family: "Space Grotesk", Inter, sans-serif; line-height: 1.2; margin: 0 0 0.8rem; }
h1 { font-size: clamp(2rem, 4vw, 3.5rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2.4rem); }
p { margin: 0 0 1rem; }
a { color: inherit; text-decoration: none; }
.container { width: min(100% - 2rem, var(--container)); margin-inline: auto; }
.section { padding: 4.5rem 0; }
.eyebrow { color: var(--primary-strong); font-weight: 700; font-size: 0.86rem; text-transform: uppercase; letter-spacing: .08em; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 90;
  background: oklch(15% 0.03 255 / 0.92);
  backdrop-filter: blur(10px);
  color: var(--text-inverse);
  border-bottom: 1px solid oklch(40% 0.03 255 / 0.35);
}
.nav-wrap { display: flex; align-items: center; justify-content: space-between; min-height: 76px; }
.logo { font-family: "Space Grotesk", sans-serif; font-weight: 700; font-size: 1.15rem; display: flex; align-items: center; gap: .55rem; }
.logo-mark {
  width: 32px; height: 32px; border-radius: 10px;
  background: linear-gradient(135deg, var(--primary), var(--accent));
}
.nav-links { display: flex; gap: 1.5rem; align-items: center; }
.nav-links a { color: oklch(93% 0.02 255); font-weight: 500; }
.nav-links a:hover, .nav-links a.active { color: white; }

.btn { display: inline-flex; align-items: center; justify-content: center; padding: .8rem 1.2rem; border-radius: 12px; font-weight: 700; border: 1px solid transparent; cursor: pointer; }
.btn-primary { background: var(--primary); color: oklch(20% 0.03 45); }
.btn-primary:hover { background: var(--primary-strong); color: #fff; }
.btn-ghost { border-color: oklch(85% 0.03 255 / 0.4); color: var(--text-inverse); }
.btn-light { background: white; color: var(--text); }

.mobile-toggle { display: none; background: none; border: 0; color: white; font-size: 1.7rem; }
.mobile-drawer {
  display: none;
  background: var(--bg-elev);
  color: var(--text-inverse);
  border-top: 1px solid oklch(45% 0.02 255 / 0.4);
  overflow: hidden;
  max-height: 0;
  transition: max-height .3s ease;
}
.mobile-drawer.open { max-height: 320px; }
.mobile-drawer nav { display: grid; gap: 1rem; padding: 1rem; }

.hero-dark {
  background: radial-gradient(circle at 10% 10%, oklch(28% 0.05 255), var(--bg));
  color: var(--text-inverse);
  padding: 5.5rem 0 4.25rem;
}
.hero-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 2rem; align-items: center; }
.hero-card {
  background: oklch(98% 0.01 255);
  border-radius: var(--radius);
  padding: 1.2rem;
  color: var(--text);
  box-shadow: var(--shadow);
}
.stat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
.stat {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 1.25rem;
  border: 1px solid var(--border);
  text-align: center;
}
.stat strong { display: block; font-family: "Space Grotesk"; font-size: 1.6rem; color: var(--primary-strong); }

.cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.1rem; }
.card { border: 1px solid var(--border); border-radius: var(--radius); padding: 1.2rem; background: white; }

.testimonial {
  background: var(--bg-elev);
  color: var(--text-inverse);
  border-radius: var(--radius);
  padding: 1.6rem;
  position: relative;
}
.carousel-controls { display: flex; gap: .8rem; margin-top: 1rem; }
.carousel-controls button { border: 0; border-radius: 10px; padding: .55rem .8rem; cursor: pointer; }

.pricing-toggle { display: inline-flex; background: var(--surface-soft); border: 1px solid var(--border); border-radius: 99px; padding: .25rem; margin-bottom: 1.4rem; }
.pricing-toggle button { border: 0; padding: .5rem .9rem; border-radius: 99px; background: transparent; font-weight: 600; cursor: pointer; }
.pricing-toggle button.active { background: var(--primary); color: oklch(20% 0.03 45); }
.pricing-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.price-card { border: 1px solid var(--border); border-radius: var(--radius); padding: 1.2rem; background: #fff; }
.price-card.featured { border-color: var(--primary); box-shadow: var(--shadow); }
.price { font-family: "Space Grotesk"; font-size: 2rem; margin: .6rem 0; }
.feature-list { padding-left: 1rem; margin: 0 0 1rem; }

.faq-item { border-bottom: 1px solid var(--border); }
.faq-q { width: 100%; text-align: left; padding: 1rem 0; border: 0; background: none; font-weight: 700; cursor: pointer; }
.faq-a { display: none; padding: 0 0 1rem; color: oklch(40% 0.03 255); }
.faq-item.open .faq-a { display: block; }

.cta-band {
  background: linear-gradient(120deg, var(--primary), var(--accent));
  color: oklch(20% 0.03 45);
  border-radius: 20px;
  padding: 2rem;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
}

form { display: grid; gap: .9rem; }
input, textarea, select {
  width: 100%; padding: .8rem .9rem; border-radius: 10px; border: 1px solid var(--border);
  font: inherit;
}
.error { color: var(--danger); font-size: .9rem; }
.success-message { display: none; margin-top: 1rem; padding: .8rem; border-radius: 10px; background: oklch(95% 0.07 150); color: oklch(30% 0.1 150); font-weight: 600; }

.site-footer { background: var(--bg); color: var(--text-inverse); padding: 2.5rem 0; margin-top: 2rem; }
.footer-grid { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; }

@media (max-width: 950px) {
  .hero-grid, .cards, .pricing-cards, .stat-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 760px) {
  .nav-links { display: none; }
  .mobile-toggle { display: block; }
  .mobile-drawer { display: block; }
  .hero-grid, .cards, .pricing-cards, .stat-grid { grid-template-columns: 1fr; }
  .cta-band { flex-direction: column; align-items: flex-start; }
}
